// Guía de marca de Kristall Film, servida en /brandguides detrás de contraseña.
// Generada desde el artifact de la guía: logo y Clash Display van embebidos en base64.
// Para actualizarla, reemplazar el string completo por el HTML nuevo.
export const GUIA_HTML: string = "<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><style>body{margin:0}img{max-width:100%}</style><title>Guía de marca Kristall</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600&family=JetBrains+Mono:wght@400;500&display=swap\">\n<style>\n@font-face{font-family:\"Clash Display\";src:url(\"data:font/woff2;base64,\") format(\"woff2\");font-weight:200 700;font-display:swap}\n/* Layout: índice lateral fijo + columna de lectura; la tira alemana abre la página como en el sitio */\n:root{\n  --bg:#F2F2F0; --surface:#FFFFFF; --fg:#0A0A0A; --fg2:#5C5C5C; --muted:#8A8A86;\n  --border:#E4E4E2; --border-strong:#C8C8C4;\n  --de-black:#1A1A1A; --de-red:#CC0000; --de-gold:#E6A800;\n  --ok:#1F7A4A; --no:#B3261E; --ok-bg:#EAF4EE; --no-bg:#FBECEA;\n  --display:\"Clash Display\",\"Arial Narrow\",Arial,sans-serif;\n  --body:\"DM Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",ui-monospace,Consolas,monospace;\n  --r:8px; --rl:12px;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){\n  --bg:#111110; --surface:#1A1A19; --fg:#F2F2F0; --fg2:#B4B4AF; --muted:#85857F;\n  --border:#2A2A28; --border-strong:#3C3C39;\n  --ok:#5CC48C; --no:#F08A80; --ok-bg:#16261C; --no-bg:#2C1714; color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#111110; --surface:#1A1A19; --fg:#F2F2F0; --fg2:#B4B4AF; --muted:#85857F;\n  --border:#2A2A28; --border-strong:#3C3C39;\n  --ok:#5CC48C; --no:#F08A80; --ok-bg:#16261C; --no-bg:#2C1714; color-scheme:dark}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--fg);font-family:var(--body);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased}\n.flag{display:flex;height:4px}.flag i{flex:1}.flag i:nth-child(1){background:var(--de-black)}.flag i:nth-child(2){background:var(--de-red)}.flag i:nth-child(3){background:var(--de-gold)}\n.wrap{max-width:1180px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;grid-template-columns:200px minmax(0,1fr);gap:56px}\nnav.toc{position:sticky;top:env(safe-area-inset-top,0px);align-self:start;padding-block:40px;display:flex;flex-direction:column;gap:2px}\nnav.toc a{color:var(--fg2);text-decoration:none;font-size:14px;padding:5px 0;border-left:2px solid transparent;padding-left:12px}\nnav.toc a:hover,nav.toc a:focus-visible{color:var(--fg);border-left-color:var(--fg);outline:none}\nmain{min-width:0;padding-block:16px 0}\nheader.hero{padding-bottom:48px;border-bottom:1px solid var(--border);margin-bottom:8px}\n.hero img.logo{width:min(340px,100%);height:auto;display:block;margin-bottom:36px}\n.eyebrow{font-size:11px;font-weight:500;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 0 10px}\nh1,h2,h3{font-family:var(--display);text-wrap:balance;letter-spacing:-.01em;margin:0}\nh1{font-size:clamp(2.2rem,5vw,3.6rem);font-weight:600;line-height:1.05}\nh2{font-size:clamp(1.7rem,3vw,2.4rem);font-weight:500;line-height:1.1}\nh3{font-size:1.2rem;font-weight:500;line-height:1.3}\n.tagline{font-family:var(--display);font-weight:500;font-size:clamp(1.1rem,2vw,1.4rem);margin:14px 0 0;color:var(--fg)}\n.lede{font-size:1.15rem;color:var(--fg2);max-width:62ch;margin:20px 0 0}\n.meta{display:flex;flex-wrap:wrap;gap:8px 20px;margin-top:28px;font-size:13px;color:var(--muted)}\nsection{padding-block:64px 8px;scroll-margin-top:16px}\nsection > .head{display:flex;flex-direction:column;gap:4px;margin-bottom:28px}\np{margin:0 0 14px;max-width:68ch}\n.stack{display:flex;flex-direction:column;gap:20px}\n.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}\n.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);padding:24px;min-width:0}\n.card h3{margin-bottom:8px}\n.card p{color:var(--fg2);font-size:15px;margin:0}\n.statement{font-family:var(--display);font-weight:500;font-size:clamp(1.3rem,2.4vw,1.75rem);line-height:1.3;max-width:34ch;margin:0 0 24px}\n.pillar .n{font-family:var(--mono);font-size:12px;color:var(--muted);margin-bottom:12px}\n.note{border-left:3px solid var(--de-gold);padding:4px 0 4px 16px;color:var(--fg2);font-size:15px;max-width:68ch}\n.note strong{color:var(--fg)}\n.tw{overflow-x:auto;border:1px solid var(--border);border-radius:var(--rl);background:var(--surface)}\ntable{border-collapse:collapse;width:100%;font-size:14.5px}\nth,td{text-align:left;padding:12px 16px;border-bottom:1px solid var(--border);vertical-align:top}\nth{font-size:11px;font-weight:500;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}\ntr:last-child td{border-bottom:0}\ntd code,p code,li code{font-family:var(--mono);font-size:.88em;background:var(--bg);padding:1px 6px;border-radius:4px;white-space:nowrap}\n.dodont{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.dd{border-radius:var(--rl);padding:18px 20px;font-size:15px;min-width:0}\n.dd .tag{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.1em;margin-bottom:8px;display:block}\n.dd.ok{background:var(--ok-bg)}.dd.ok .tag{color:var(--ok)}\n.dd.no{background:var(--no-bg)}.dd.no .tag{color:var(--no)}\n.dd q{quotes:\"«\" \"»\";display:block}\nul.rules{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:8px;max-width:68ch}\nul.rules li::marker{color:var(--muted)}\n.swatches{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}\n.sw{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);overflow:hidden}\n.sw .chip{height:84px;border-bottom:1px solid var(--border)}\n.sw .info{padding:12px 14px;font-size:13px}\n.sw .info b{display:block;font-weight:500;font-size:14px}\n.sw .info span{font-family:var(--mono);color:var(--fg2);font-size:12px}\n.logo-stage{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.stage{border-radius:var(--rl);padding:40px 28px;display:flex;align-items:center;justify-content:center;min-height:170px;border:1px solid var(--border)}\n.stage img{width:min(300px,100%);height:auto}\n.stage.light{background:#F2F2F0}.stage.dark{background:#0A0A0A;border-color:#0A0A0A}\n.stage.safe{position:relative;background:#FFFFFF}\n.stage.safe .box{outline:1px dashed #CC0000;outline-offset:22px}\n.caption{font-size:13px;color:var(--muted);margin-top:8px}\n.lines{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}\n.line{background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:14px;font-size:13px;min-width:0}\n.line b{font-family:var(--display);font-weight:500;font-size:16px;display:block}\n.line span{color:var(--fg2)}\n.typespec{background:var(--surface);border:1px solid var(--border);border-radius:var(--rl);padding:28px;display:flex;flex-direction:column;gap:22px}\n.typespec .row{display:grid;grid-template-columns:150px minmax(0,1fr);gap:16px;align-items:baseline;border-bottom:1px solid var(--border);padding-bottom:18px}\n.typespec .row:last-child{border-bottom:0;padding-bottom:0}\n.typespec .lbl{font-size:12px;color:var(--muted);font-family:var(--mono)}\n.label-mock{background:#FFFFFF;color:#0A0A0A;border:1px solid #C8C8C4;border-radius:var(--r);padding:18px;display:grid;grid-template-columns:minmax(0,1fr) 84px;gap:16px;max-width:440px}\n.label-mock .k{font-family:var(--display);font-weight:600;font-size:22px;line-height:1}\n.label-mock .s{font-family:var(--mono);font-size:11.5px;color:#5C5C5C;line-height:1.7;margin-top:10px}\n.qr{width:84px;height:84px;background:repeating-conic-gradient(#0A0A0A 0 25%,#FFFFFF 0 50%) 0 0/14px 14px;border:6px solid #FFFFFF;outline:1px solid #0A0A0A}\n.label-mock .bar{grid-column:1/-1;display:flex;height:3px}.label-mock .bar i{flex:1}\n.label-mock .bar i:nth-child(1){background:#1A1A1A}.label-mock .bar i:nth-child(2){background:#CC0000}.label-mock .bar i:nth-child(3){background:#E6A800}\n.pending{display:inline-block;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#7A5500;background:#FFF3D1;border-radius:999px;padding:2px 9px;vertical-align:middle;margin-left:6px}\nfooter{border-top:1px solid var(--border);margin-top:64px;padding-top:24px;font-size:13px;color:var(--muted)}\n@media (max-width:900px){\n  .wrap{grid-template-columns:minmax(0,1fr);gap:0}\n  nav.toc{position:static;flex-direction:row;flex-wrap:wrap;gap:6px;padding-block:20px 0}\n  nav.toc a{border:1px solid var(--border);border-radius:999px;padding:4px 12px;font-size:13px;background:var(--surface)}\n  main{padding-top:24px}\n}\n@media (max-width:640px){\n  .grid2,.grid3,.dodont,.logo-stage{grid-template-columns:minmax(0,1fr)}\n  .typespec .row{grid-template-columns:minmax(0,1fr);gap:4px}\n  .card{padding:20px}\n}\n@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\nhtml{scroll-behavior:smooth}\n/* ---- Ornamentos del sitio (kristall-web) ---- */\n@keyframes kf-rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}\n@keyframes kf-rise-solid{from{transform:translateY(18px)}to{transform:none}}\n@keyframes kf-marquee{to{transform:translateX(-50%)}}\n.kf-rise{animation:kf-rise .8s cubic-bezier(.2,.7,.2,1) both}\n.kf-rise-solid{animation:kf-rise-solid .8s cubic-bezier(.2,.7,.2,1) both}\n.flagchip{display:inline-flex;width:24px;height:12px;border-radius:2px;overflow:hidden;flex-shrink:0}\n.flagchip i{flex:1}.flagchip i:nth-child(1){background:#1A1A1A;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)}.flagchip i:nth-child(2){background:#CC0000}.flagchip i:nth-child(3){background:#E6A800}\n.bars{display:flex;gap:3px;margin-bottom:14px}.bars i{width:20px;height:3px;border-radius:2px}\n.bars i:nth-child(1){background:var(--fg)}.bars i:nth-child(2){background:#CC0000}.bars i:nth-child(3){background:#E6A800}\n.cover{position:relative;isolation:isolate;overflow:hidden;background:#0A0A0A;color:#FFFFFF}\n.cover::before{content:\"\";position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at center,#2a2a2a 0%,#0A0A0A 70%)}\n.cover::after{content:\"\";position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at bottom,rgba(230,168,0,.12),transparent 60%)}\n.cover-in{max-width:1180px;margin:0 auto;padding:28px max(16px,env(safe-area-inset-right,0px)) 56px max(16px,env(safe-area-inset-left,0px))}\n.cover-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:72px}\n.cover-top img{width:min(200px,50vw);height:auto;display:block}\n.pill{border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.05);border-radius:999px;padding:4px 12px;font-size:11px;font-weight:500;text-transform:uppercase;letter-spacing:.14em;color:rgba(255,255,255,.8);white-space:nowrap}\n.kicker{font-family:var(--display);font-size:clamp(1.6rem,3vw,2.25rem);line-height:1.1;letter-spacing:-.01em;margin:0 0 28px;color:rgba(255,255,255,.55)}\n.kicker b{display:block;font-weight:700;color:#FFFFFF}.kicker span{display:block;font-weight:400}\n.cover .gold{display:flex;align-items:center;gap:12px;font-size:12px;font-weight:500;text-transform:uppercase;letter-spacing:.16em;color:#E6A800;margin:0 0 18px}\n.cover h1{color:#FFFFFF;max-width:20ch;font-size:clamp(2.4rem,6vw,4.4rem);line-height:.98}\n.cover .tagline{color:rgba(255,255,255,.55);font-size:clamp(1.3rem,2.6vw,1.9rem);margin-top:10px}\n.cover .lede{color:rgba(255,255,255,.7);max-width:58ch}\n.glass{display:flex;flex-wrap:wrap;gap:12px;margin-top:36px}\n.glass div{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:var(--rl);padding:16px 20px;min-width:140px}\n.glass b{display:block;font-family:var(--display);font-weight:500;font-size:1.5rem;line-height:1.1}\n.glass span{display:block;font-size:12px;color:rgba(255,255,255,.45);margin-top:4px}\n.cover .d1{animation-delay:120ms}.cover .d2{animation-delay:240ms}.cover .d3{animation-delay:360ms}\n.marquee{overflow:hidden;border-bottom:1px solid var(--border);padding:22px 0;-webkit-mask-image:linear-gradient(to right,transparent,#000 48px,#000 calc(100% - 48px),transparent);mask-image:linear-gradient(to right,transparent,#000 48px,#000 calc(100% - 48px),transparent)}\n.marquee .track{display:flex;width:max-content;animation:kf-marquee 60s linear infinite}\n.marquee:hover .track{animation-play-state:paused}\n.marquee img{height:22px;width:auto;margin:0 22px;opacity:.4;flex-shrink:0}\n.pillar .n{font-family:var(--display);font-weight:600;font-size:2.4rem;line-height:1;color:var(--fg);margin-bottom:16px;display:flex;align-items:flex-end;justify-content:space-between}\n.pillar .n .flagchip{margin-bottom:6px}\nfooter.site{margin-top:0;border-top:0;padding:0;background:#1A1A1A;color:rgba(255,255,255,.5);font-size:13px}\nfooter.site .in{max-width:1180px;margin:0 auto;padding:40px max(16px,env(safe-area-inset-right,0px)) calc(32px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px));display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end}\nfooter.site img{height:30px;width:auto;opacity:.6;display:block;margin-bottom:14px}\nfooter.site p{margin:0;max-width:62ch}\nfooter.site code{background:rgba(255,255,255,.08);color:rgba(255,255,255,.75)}\nfooter.site .tl{font-family:var(--display);font-weight:500;font-size:1.1rem;color:#FFFFFF;text-align:right}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]) .marquee img{filter:invert(1)}}\n:root[data-theme=\"dark\"] .marquee img{filter:invert(1)}\n@media (max-width:640px){.cover-top{margin-bottom:48px}footer.site .in{grid-template-columns:minmax(0,1fr)}footer.site .tl{text-align:left}}\n@media (prefers-reduced-motion:reduce){.kf-rise,.kf-rise-solid,.marquee .track{animation:none}}\n</style></head><body>\n<div class=\"flag\" aria-hidden=\"true\"><i></i><i></i><i></i></div>\n<header class=\"cover\">\n<div class=\"cover-in\">\n  <div class=\"cover-top\"><img src=\"/cat/logob.svg\" alt=\"Kristall\"><span class=\"pill\">Uso interno</span></div>\n  <p class=\"gold kf-rise d1\"><span class=\"flagchip\" aria-hidden=\"true\"><i></i><i></i><i></i></span>Guía de marca · versión 1.3</p>\n  <h1 class=\"kf-rise-solid d1\">Cómo se ve, cómo habla y cómo se usa Kristall Film</h1>\n  <p class=\"tagline kf-rise-solid d2\">Performance aplicada al confort.</p>\n  <p class=\"lede kf-rise-solid d2\">Para el equipo, para quien diseñe una pieza y para los talleres que trabajan con la marca. Cuando algo no esté acá, la regla es la de siempre: sobriedad, dato concreto y respeto por el oficio.</p>\n  <div class=\"glass kf-rise d3\">\n    <div><b>3</b><span>pilares de marca</span></div>\n    <div><b>13</b><span>líneas de producto</span></div>\n    <div><b>11</b><span>capítulos</span></div>\n    <div><b>Nov 2026</b><span>última revisión</span></div>\n  </div>\n</div>\n</header>\n<div class=\"marquee\" aria-hidden=\"true\"><div class=\"track\"><img src=\"/Productos/logo-linea/klass.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kron.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kore.svg\" alt=\"\"><img src=\"/Productos/logo-linea/karbon.svg\" alt=\"\"><img src=\"/Productos/logo-linea/keramx.svg\" alt=\"\"><img src=\"/Productos/logo-linea/krypton.svg\" alt=\"\"><img src=\"/Productos/logo-linea/ppf.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kaiser.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kreflect.svg\" alt=\"\"><img src=\"/Productos/logo-linea/klear.svg\" alt=\"\"><img src=\"/Productos/logo-linea/knight.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kwhite.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kdecor.svg\" alt=\"\"><img src=\"/Productos/logo-linea/klass.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kron.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kore.svg\" alt=\"\"><img src=\"/Productos/logo-linea/karbon.svg\" alt=\"\"><img src=\"/Productos/logo-linea/keramx.svg\" alt=\"\"><img src=\"/Productos/logo-linea/krypton.svg\" alt=\"\"><img src=\"/Productos/logo-linea/ppf.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kaiser.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kreflect.svg\" alt=\"\"><img src=\"/Productos/logo-linea/klear.svg\" alt=\"\"><img src=\"/Productos/logo-linea/knight.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kwhite.svg\" alt=\"\"><img src=\"/Productos/logo-linea/kdecor.svg\" alt=\"\"></div></div>\n<div class=\"wrap\">\n<nav class=\"toc\" aria-label=\"Secciones\">\n  <a href=\"#esencia\">Esencia</a>\n  <a href=\"#arquitectura\">Arquitectura de marca</a>\n  <a href=\"#voz\">Voz y tono</a>\n  <a href=\"#glosario\">Glosario técnico</a>\n  <a href=\"#logo\">Logo</a>\n  <a href=\"#color\">Color</a>\n  <a href=\"#tipografia\">Tipografía</a>\n  <a href=\"#fotografia\">Fotografía</a>\n  <a href=\"#talleres\">Uso por talleres</a>\n  <a href=\"#redes\">Redes sociales</a>\n  <a href=\"#packaging\">Packaging y etiquetas</a>\n</nav>\n\n<main>\n\n<!-- ESENCIA -->\n<section id=\"esencia\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">01 · Esencia</p><h2>Qué es Kristall Film</h2></div>\n  <p class=\"statement\">Láminas de control solar, seguridad y protección para el profesional que las instala, con una garantía que se puede seguir rollo por rollo.</p>\n  <div class=\"stack\">\n    <div class=\"grid2\">\n      <div class=\"card\"><p class=\"eyebrow\">Público principal</p><h3>Instaladores y talleres</h3><p>El polarizador que compra rollos y los coloca. Toda la comunicación se piensa primero para esta persona: qué necesita saber para vender, instalar y respaldar el trabajo.</p></div>\n      <div class=\"card\"><p class=\"eyebrow\">Público secundario</p><h3>Distribuidores y revendedores</h3><p>Compran volumen y abastecen a talleres. Necesitan condiciones claras, stock confiable y material que puedan pasarle a sus clientes sin rehacerlo.</p></div>\n    </div>\n    <p>El dueño del auto o de la obra es el destino final del producto, pero llega a la marca a través del instalador. Le hablamos directo solo en la garantía (activación y consulta) y en la web pública.</p>\n    <h3 style=\"margin-top:12px\">Los tres pilares</h3>\n    <div class=\"grid3\">\n      <div class=\"card pillar\"><div class=\"n\">01<span class=\"flagchip\" aria-hidden=\"true\"><i></i><i></i><i></i></span></div><h3>Garantía trazable</h3><p>Cada rollo tiene un código propio y cada instalación una garantía que el cliente activa y consulta online. Es la prueba de que el producto es original.</p></div>\n      <div class=\"card pillar\"><div class=\"n\">02<span class=\"flagchip\" aria-hidden=\"true\"><i></i><i></i><i></i></span></div><h3>Respaldo al instalador</h3><p>Portal con compras, stock y garantías, soporte técnico y acompañamiento comercial. El taller no queda solo después de la venta.</p></div>\n      <div class=\"card pillar\"><div class=\"n\">03<span class=\"flagchip\" aria-hidden=\"true\"><i></i><i></i><i></i></span></div><h3>Rendimiento técnico</h3><p>VLT, rechazo UV e infrarrojo, espesor y años de garantía publicados por producto. Lo que se promete se puede medir.</p></div>\n    </div>\n    <div class=\"card\"><p class=\"eyebrow\">Tagline</p><h3>Performance aplicada al confort</h3><p>Resume la promesa: rendimiento técnico medible que se traduce en un auto o un ambiente más fresco, protegido y cómodo. Va debajo o al lado del logo en piezas institucionales (web, catálogo, packaging, firma de mail). Se escribe siempre igual, con mayúscula inicial y punto final cuando va sola. No se traduce ni se reformula, y no se usa como título de una pieza de producto.</p></div>\n    <div class=\"note\"><strong>El origen alemán es respaldo, no titular.</strong> Sigue presente en el logo, la tira de color y la ficha técnica, pero ningún mensaje principal se apoya solo en él. Primero va un pilar; lo alemán lo confirma.</div>\n    <div class=\"grid2\">\n      <div class=\"card\"><p class=\"eyebrow\">Posición de precio</p><h3>Premium accesible</h3><p>Calidad de primera línea a un precio razonable frente a las marcas top. No se comunica como \"barato\" ni como \"lo más caro\": se comunica el valor (garantía, respaldo, rendimiento).</p></div>\n      <div class=\"card\"><p class=\"eyebrow\">Líneas de producto</p><h3>Todas empiezan con K</h3><p>Los nombres de línea se escriben siempre igual: Klass, Kron, Kore, Karbon, Keram X, Krypton, Kaiser, KReflect Silver, Klear, KNight, KWhite Matte, KDecor Stripe. Más PPF.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ARQUITECTURA -->\n<section id=\"arquitectura\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">02 · Arquitectura de marca</p><h2>Kristall reemplaza a Dr. Polarizados</h2></div>\n  <p>Ante el público queda una sola marca visible: Kristall Film. Dr. Polarizados se va retirando de la comunicación y no se crean piezas nuevas con su nombre.</p>\n  <div class=\"tw\"><table>\n    <thead><tr><th>Dónde</th><th>Qué hacer</th></tr></thead>\n    <tbody>\n      <tr><td>Piezas nuevas (web, redes, packaging, mails)</td><td>Solo Kristall Film. Sin co-branding con Dr. Polarizados.</td></tr>\n      <tr><td>Documentos comerciales y legales</td><td>La razón social sigue figurando donde la ley lo pide (facturas, remitos, términos). Es dato, no marca: va en texto chico, sin logo.</td></tr>\n      <tr><td>Contactos que conocen a Dr. Polarizados</td><td>Una línea de transición cuando haga falta: «Dr. Polarizados ahora es Kristall Film». Sin anuncios largos ni explicaciones.</td></tr>\n      <tr><td>Material existente</td><td>Se reemplaza cuando se reimprime o se actualiza, no hace falta retirarlo de golpe.</td></tr>\n    </tbody>\n  </table></div>\n  <p class=\"caption\">Cómo se nombra la marca: <b>Kristall Film</b> en texto. <b>Kristall</b> solo cuando ya se nombró antes o en espacios muy cortos. Nunca «Kristal», «Cristal Film» ni «KRISTALL FILM» en mayúsculas dentro de un texto.</p>\n</section>\n\n<!-- VOZ -->\n<section id=\"voz\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">03 · Voz y tono</p><h2>Técnica y precisa, cercana y cálida</h2></div>\n  <p>Hablamos como alguien que sabe del producto y quiere que al taller le vaya bien. Damos el dato exacto y lo explicamos con amabilidad. Tratamos de <b>vos</b>, en español rioplatense.</p>\n  <div class=\"grid2\">\n    <div class=\"card\"><h3>Técnica y precisa</h3><p>Números reales, nombres correctos, nada de vaguedades. Si decimos que algo rechaza calor, decimos cuánto.</p></div>\n    <div class=\"card\"><h3>Cercana y cálida</h3><p>Frases cortas, trato directo, disposición a ayudar. Somos el proveedor que atiende el teléfono.</p></div>\n  </div>\n  <h3 style=\"margin:32px 0 12px\">Cómo se nota en la práctica</h3>\n  <div class=\"stack\">\n    <div class=\"dodont\">\n      <div class=\"dd ok\"><span class=\"tag\">Así</span><q>Keram X 15 deja pasar el 15% de la luz visible y tiene 10 años de garantía.</q></div>\n      <div class=\"dd no\"><span class=\"tag\">Así no</span><q>¡La mejor lámina cerámica del mercado, calidad insuperable!</q></div>\n    </div>\n    <div class=\"dodont\">\n      <div class=\"dd ok\"><span class=\"tag\">Así</span><q>Activá la garantía con el código de tu rollo. Tarda dos minutos.</q></div>\n      <div class=\"dd no\"><span class=\"tag\">Así no</span><q>Estimado cliente, le solicitamos proceda a la activación de su garantía.</q></div>\n    </div>\n    <div class=\"dodont\">\n      <div class=\"dd ok\"><span class=\"tag\">Así</span><q>Si tenés dudas con la instalación, escribinos y te ayudamos.</q></div>\n      <div class=\"dd no\"><span class=\"tag\">Así no</span><q>¡¡APROVECHÁ!! Solo por hoy, últimos rollos.</q></div>\n    </div>\n  </div>\n  <h3 style=\"margin:32px 0 12px\">Lo que nunca hacemos</h3>\n  <ul class=\"rules\">\n    <li><b>Hablar mal de otras marcas.</b> No nombramos ni desacreditamos a la competencia. Comparamos contra un dato, no contra un nombre.</li>\n    <li><b>Prometer sin dato.</b> «El mejor», «insuperable», «el más resistente» no van si no hay un número o una prueba detrás.</li>\n    <li><b>Tono de oferta.</b> Sin urgencia falsa, sin mayúsculas gritadas, sin signos de exclamación dobles.</li>\n    <li><b>Jerga sin explicar.</b> La primera vez que aparece una sigla, se dice qué significa (ver el glosario).</li>\n  </ul>\n  <h3 style=\"margin:32px 0 12px\">El tono según con quién hablamos</h3>\n  <div class=\"tw\"><table>\n    <thead><tr><th>Con quién</th><th>Tono</th><th>Ejemplo</th></tr></thead>\n    <tbody>\n      <tr><td>Instalador</td><td>De colega. Directo, práctico, va al dato técnico sin rodeos.</td><td>«Karbon tiene 10 años de garantía. Si lo pedís hoy, sale mañana.»</td></tr>\n      <tr><td>Distribuidor</td><td>Comercial y claro. Condiciones, plazos y stock por escrito.</td><td>«Tenés 12 rollos de Kore reservados hasta el viernes.»</td></tr>\n      <tr><td>Usuario final</td><td>Simple y tranquilizador. Cero siglas sin explicar.</td><td>«Tu garantía está activa hasta marzo de 2036.»</td></tr>\n      <tr><td>Un reclamo</td><td>Serio y resolutivo. Qué pasó, qué hacemos y cuándo.</td><td>«Recibimos tu reclamo. Lo revisa un técnico en 48 h hábiles.»</td></tr>\n    </tbody>\n  </table></div>\n</section>\n\n<!-- GLOSARIO -->\n<section id=\"glosario\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">04 · Glosario técnico</p><h2>Cómo se escriben los datos</h2></div>\n  <p>Cada sigla se escribe siempre igual y se explica la primera vez que aparece en una pieza. Los porcentajes van pegados al número, sin espacio: <code>15%</code>.</p>\n  <div class=\"tw\"><table>\n    <thead><tr><th>Término</th><th>Qué significa</th><th>Cómo se escribe</th></tr></thead>\n    <tbody>\n      <tr><td><b>VLT</b></td><td>Transmisión de luz visible. Cuánta luz deja pasar la lámina: cuanto más bajo, más oscura.</td><td><code>VLT 15%</code> · en texto corrido: «deja pasar el 15% de la luz»</td></tr>\n      <tr><td><b>UVR</b></td><td>Rechazo de rayos ultravioleta.</td><td><code>UVR 99%</code> · «bloquea el 99% de los rayos UV»</td></tr>\n      <tr><td><b>IRR</b></td><td>Rechazo de infrarrojo, la parte de la radiación que se siente como calor.</td><td><code>IRR 20%</code> · «rechaza el 20% del infrarrojo»</td></tr>\n      <tr><td><b>TSER</b></td><td>Rechazo total de energía solar. El número que mejor resume cuánto calor frena.</td><td><code>TSER 55%</code> (solo cuando el dato existe en la ficha)</td></tr>\n      <tr><td><b>PPF</b></td><td>Film de protección de pintura. Transparente, en TPU, se regenera ante rayones finos.</td><td><code>PPF</code> · «film de protección de pintura (PPF)»</td></tr>\n      <tr><td><b>Ply</b></td><td>Capas de la lámina. Indica espesor.</td><td><code>1 ply</code>, <code>2 ply</code></td></tr>\n      <tr><td><b>Tecnología</b></td><td>Cómo está fabricada: teñida, metalizada, carbono o cerámica.</td><td>Teñida (Dyed) · Sputtering · Nano Carbon · Nano Ceramic. En español primero cuando haya traducción.</td></tr>\n      <tr><td><b>Garantía</b></td><td>Años de cobertura por producto.</td><td><code>10 años de garantía</code> · nunca «garantía de por vida»</td></tr>\n    </tbody>\n  </table></div>\n  <p class=\"caption\">Los valores salen siempre de la ficha del producto (la planilla del catálogo). Si un dato no está en la ficha, no se publica.</p>\n</section>\n\n<!-- LOGO -->\n<section id=\"logo\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">05 · Logo</p><h2>El sello KRISTALL</h2></div>\n  <p>El logo es un sello: la palabra KRISTALL dentro de una cápsula con contorno negro y la bandera alemana asomando por detrás a la derecha. Se usa siempre completo, con la bandera y la ®.</p>\n  <div class=\"logo-stage\">\n    <div><div class=\"stage light\"><img src=\"data:image/png;base64,\" alt=\"Logo sobre fondo claro\"></div><p class=\"caption\">Sobre fondo claro (uso principal). Archivo: <code>LogoPlano.png</code></p></div>\n    <div><div class=\"stage dark\"><img src=\"data:image/png;base64,\" alt=\"Logo sobre fondo oscuro\"></div><p class=\"caption\">Sobre fondo oscuro: la cápsula blanca lo separa del fondo. Para el footer existe <code>cat/logob.svg</code>.</p></div>\n  </div>\n  <div class=\"grid2\" style=\"margin-top:12px\">\n    <div class=\"card\"><h3>Área de resguardo</h3><p>Alrededor del logo queda libre un espacio igual a la altura de la letra K. Ningún texto, borde ni foto entra en ese margen.</p></div>\n    <div class=\"card\"><h3>Tamaño mínimo</h3><p>160 px de ancho en pantalla y 40 mm en impresión. Por debajo de eso la bandera deja de leerse; usar el favicon o el sticker reducido.</p></div>\n  </div>\n  <h3 style=\"margin:32px 0 12px\">No se hace</h3>\n  <ul class=\"rules\">\n    <li>Cambiar los colores, quitar la bandera o recolorearla.</li>\n    <li>Estirar, inclinar, rotar o recortar la cápsula.</li>\n    <li>Escribir «KRISTALL» con otra tipografía para imitar el logo.</li>\n    <li>Ponerlo sobre una foto con mucho detalle sin que la cápsula quede bien separada del fondo.</li>\n    <li>Agregarle sombras, brillos, contornos extra o efectos 3D.</li>\n  </ul>\n  <h3 style=\"margin:32px 0 12px\">Logos de línea</h3>\n  <p>Cada línea tiene su logotipo (en <code>public/Productos/logo-linea/</code>). Se usan en la ficha de producto, el catálogo y el packaging, siempre acompañando al logo principal y nunca en su lugar.</p>\n  <div class=\"lines\">\n    <div class=\"line\"><b>Klass · Kron</b><span>Autos · teñida · 3 años</span></div>\n    <div class=\"line\"><b>Kore</b><span>Autos · sputtering · 5 años</span></div>\n    <div class=\"line\"><b>Karbon · Keram X</b><span>Autos · carbono y cerámica · 10 años</span></div>\n    <div class=\"line\"><b>Krypton</b><span>Autos · seguridad · 10 años</span></div>\n    <div class=\"line\"><b>PPF</b><span>Protección de pintura · 15 años</span></div>\n    <div class=\"line\"><b>Kaiser</b><span>Arquitectura · cerámica · 10 años</span></div>\n    <div class=\"line\"><b>KReflect · Klear</b><span>Arquitectura · espejado, seguridad · 6 años</span></div>\n    <div class=\"line\"><b>KNight · KWhite · KDecor</b><span>Arquitectura · decorativas · 6 años</span></div>\n  </div>\n</section>\n\n<!-- COLOR -->\n<section id=\"color\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">06 · Color</p><h2>Negro para actuar, bandera para firmar</h2></div>\n  <p>La marca es casi monocroma. El negro es el único color de acción. Los tres colores de la bandera alemana aparecen juntos como tira, y la tira se mantiene como elemento recurrente en el sitio, las piezas y las etiquetas.</p>\n  <div class=\"swatches\">\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#0A0A0A\"></div><div class=\"info\"><b>Negro acción</b><span>#0A0A0A</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#F2F2F0\"></div><div class=\"info\"><b>Fondo</b><span>#F2F2F0</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#FFFFFF\"></div><div class=\"info\"><b>Superficie</b><span>#FFFFFF</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#5C5C5C\"></div><div class=\"info\"><b>Texto secundario</b><span>#5C5C5C</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#E4E4E2\"></div><div class=\"info\"><b>Borde</b><span>#E4E4E2</span></div></div>\n  </div>\n  <p class=\"eyebrow\" style=\"margin-top:28px\">Bandera · solo juntos, solo decorativos</p>\n  <div class=\"swatches\">\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#1A1A1A\"></div><div class=\"info\"><b>Negro bandera</b><span>#1A1A1A</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#CC0000\"></div><div class=\"info\"><b>Rojo bandera</b><span>#CC0000</span></div></div>\n    <div class=\"sw\"><div class=\"chip\" style=\"background:#E6A800\"></div><div class=\"info\"><b>Dorado bandera</b><span>#E6A800</span></div></div>\n  </div>\n  <ul class=\"rules\" style=\"margin-top:24px\">\n    <li>Botones y llamados a la acción: siempre negro. Nunca rojo ni dorado.</li>\n    <li>El fondo de una página nunca es blanco puro: es <code>#F2F2F0</code>. El blanco es para tarjetas y paneles.</li>\n    <li>La tira de bandera va en este orden (negro, rojo, dorado), horizontal y de punta a punta del elemento que la lleva.</li>\n    <li>No se agregan otros colores saturados. Verde y rojo de estado solo en interfaces (garantía activa, error).</li>\n  </ul>\n</section>\n\n<!-- TIPOGRAFIA -->\n<section id=\"tipografia\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">07 · Tipografía</p><h2>Clash Display y DM Sans</h2></div>\n  <p>Clash Display vende: títulos, hero y nombres de producto. DM Sans informa: textos, interfaz y etiquetas. Ninguna otra familia en piezas de marca.</p>\n  <div class=\"typespec\">\n    <div class=\"row\"><span class=\"lbl\">Display · Clash 600</span><span style=\"font-family:var(--display);font-weight:600;font-size:clamp(1.8rem,4vw,2.8rem);line-height:1.05;letter-spacing:-.01em\">Keram X 15</span></div>\n    <div class=\"row\"><span class=\"lbl\">Título · Clash 500</span><span style=\"font-family:var(--display);font-weight:500;font-size:1.6rem;line-height:1.15\">Diez años de garantía, rollo por rollo</span></div>\n    <div class=\"row\"><span class=\"lbl\">Texto · DM Sans 400</span><span style=\"font-size:16px;color:var(--fg2)\">Lámina de nano cerámica que rechaza el calor sin oscurecer de más. Ideal para parabrisas laterales y luneta.</span></div>\n    <div class=\"row\"><span class=\"lbl\">Etiqueta · DM Sans 500</span><span style=\"font-size:11px;font-weight:500;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)\">Línea premium · Autos</span></div>\n  </div>\n  <p class=\"caption\">Cuando una herramienta no tenga Clash Display (por ejemplo, el conector de Figma), se usa Arial o Arimo como reemplazo provisorio y se cambia antes de publicar.</p>\n</section>\n\n<!-- FOTOGRAFIA -->\n<section id=\"fotografia\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">08 · Fotografía</p><h2>Auto terminado y obra terminada</h2></div>\n  <p>Mostramos el resultado, no el proceso. Dos familias de fotos:</p>\n  <div class=\"grid2\">\n    <div class=\"card\"><h3>Auto de estudio</h3><p>Vehículo con la lámina ya colocada, luz controlada, fondo limpio o neutro. Se ve el auto entero o un detalle de vidrio con reflejo prolijo. Estética premium, sin exageraciones.</p></div>\n    <div class=\"card\"><h3>Arquitectura</h3><p>Fachadas, oficinas y viviendas con la lámina instalada. Se privilegia la luz natural, las líneas rectas y el contraste entre interior y exterior.</p></div>\n  </div>\n  <ul class=\"rules\" style=\"margin-top:24px\">\n    <li>Colores naturales y contraste moderado. Sin filtros saturados ni viñetas.</li>\n    <li>Nada de personas posando con el producto ni fotos de stock genéricas.</li>\n    <li>Las patentes se tapan o se difuminan siempre.</li>\n    <li>Si la foto muestra un tono de lámina, el texto dice cuál es (línea y VLT).</li>\n  </ul>\n</section>\n\n<!-- TALLERES -->\n<section id=\"talleres\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">09 · Uso por talleres</p><h2>Instaladores que muestran la marca</h2></div>\n  <p>Queremos que los talleres usen Kristall Film en su local, su vehículo y sus redes. Para que la marca se vea igual en todos lados, estas son las condiciones.</p>\n  <div class=\"note\" style=\"margin-bottom:20px\"><strong>El sello «Instalador oficial Kristall Film» no es de libre uso.</strong> Solo lo usan los talleres habilitados. Ser cliente o tener cuenta en el Portal no alcanza.</div>\n  <h3 style=\"margin:8px 0 12px\">Programa Instalador oficial</h3>\n  <div class=\"tw\"><table>\n    <thead><tr><th>Requisito</th><th>Cómo se mide</th></tr></thead>\n    <tbody>\n      <tr><td><b>Antigüedad</b></td><td>12 meses como cliente de Kristall antes de pedir el sello.</td></tr>\n      <tr><td><b>Volumen de compra</b></td><td>6 rollos o más por trimestre.</td></tr>\n      <tr><td><b>Capacitación</b></td><td>Haber hecho la capacitación de instalación y producto de Kristall.</td></tr>\n      <tr><td><b>Calidad comprobada</b></td><td>5 fotos de trabajos terminados aprobadas por Kristall, y ningún reclamo de garantía por mala instalación en el trimestre.</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"grid2\" style=\"margin-top:12px\">\n    <div class=\"card\"><h3>Qué recibe el taller</h3><p>Aparece en el buscador de instaladores de kristallfilm.com, recibe las consultas de clientes finales de su zona, el kit de marca (sello, plantillas de redes, vinilo para vidriera e impresos) y mejores condiciones comerciales.</p></div>\n    <div class=\"card\"><h3>Quién decide y cada cuánto</h3><p>La habilitación se marca en la ficha del contacto en el CRM y solo un SUPERADMIN puede darla o quitarla. Se revisa cada trimestre: si el taller no cumple, pierde el sello y retira la marca de oficial de su local, vehículo y redes.</p></div>\n  </div>\n  <div style=\"height:20px\"></div>\n  <div class=\"grid2\">\n    <div class=\"card\"><h3>Qué pueden usar</h3><p>El logo principal, descargado del material oficial. El sello «Instalador oficial», solo si el taller está habilitado. Fotos y textos de producto del sitio, sin modificar los datos técnicos.</p></div>\n    <div class=\"card\"><h3>Dónde</h3><p>Fachada y vidriera del local, vehículo de trabajo, ropa del equipo, perfiles de redes, presupuestos y tarjetas.</p></div>\n  </div>\n  <ul class=\"rules\" style=\"margin-top:24px\">\n    <li>El logo se usa tal cual se entrega, con su área de resguardo. Sin redibujar ni cambiar colores.</li>\n    <li>La marca del taller manda: el logo de Kristall Film acompaña, nunca se presenta como si el taller fuera Kristall.</li>\n    <li>En una misma pieza no se mezcla Kristall Film con logos de otras marcas de láminas.</li>\n    <li>Las garantías se comunican con los años de la ficha. El taller no puede ofrecer más cobertura en nombre de Kristall.</li>\n    <li>Ante la duda, el taller consulta antes de imprimir.</li>\n  </ul>\n  <div class=\"note\" style=\"margin-top:20px\"><strong>Pendiente:</strong> diseñar el sello «Instalador oficial Kristall Film» y armar el kit descargable (logo, sello, plantillas de redes) dentro del Portal de Cliente, visible solo para talleres habilitados.</div>\n</section>\n\n<!-- REDES -->\n<section id=\"redes\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">10 · Redes sociales</p><h2>Instagram y compañía</h2></div>\n  <p>Cuenta principal: <code>@kristallfilm.la</code>. En redes vale la misma voz: dato concreto, trato de vos, sin gritar ofertas.</p>\n  <div class=\"tw\"><table>\n    <thead><tr><th>Formato</th><th>Medida</th><th>Uso</th></tr></thead>\n    <tbody>\n      <tr><td>Post vertical</td><td>1080 × 1350 (4:5)</td><td>Producto, trabajo terminado, dato técnico</td></tr>\n      <tr><td>Carrusel</td><td>1080 × 1350 (4:5)</td><td>Comparativas de VLT, explicaciones paso a paso</td></tr>\n      <tr><td>Reel / historia</td><td>1080 × 1920 (9:16)</td><td>Resultado antes y después, novedades, turnos</td></tr>\n    </tbody>\n  </table></div>\n  <ul class=\"rules\" style=\"margin-top:24px\">\n    <li>Texto sobre foto: máximo una línea de título en Clash Display y una de apoyo en DM Sans, siempre sobre una zona limpia de la imagen o una franja negra.</li>\n    <li>El logo va abajo, chico, con su resguardo. La tira de bandera puede cerrar la pieza en el borde inferior.</li>\n    <li>No se publican precios de rollos. Se deriva a WhatsApp o al instalador más cercano.</li>\n    <li>Comentarios: se responden con la misma voz, rápido y sin discutir. Las quejas pasan a mensaje privado con una respuesta pública corta: «Te escribimos por privado para resolverlo».</li>\n    <li>Hashtags: pocos y en español. Nada de listas de 20.</li>\n  </ul>\n</section>\n\n<!-- PACKAGING -->\n<section id=\"packaging\">\n  <div class=\"head\"><div class=\"bars\" aria-hidden=\"true\"><i></i><i></i><i></i></div><p class=\"eyebrow\">11 · Packaging y etiquetas</p><h2>El rollo también comunica</h2></div>\n  <p>La etiqueta del rollo es donde se cruzan la marca y la garantía. Tiene que identificar el producto de un vistazo y llevar al cliente a su garantía.</p>\n  <div class=\"label-mock\" aria-label=\"Ejemplo de etiqueta de rollo\">\n    <div>\n      <div class=\"k\">Keram X 15</div>\n      <div class=\"s\">VLT 15% · UVR 99%<br>Nano Ceramic · 10 años<br>LOT-2026-11-R003</div>\n    </div>\n    <div class=\"qr\" role=\"img\" aria-label=\"Código QR del rollo\"></div>\n    <div class=\"bar\"><i></i><i></i><i></i></div>\n  </div>\n  <p class=\"caption\">Ejemplo ilustrativo. El QR codifica el código del rollo, igual que lo genera el CRM.</p>\n  <ul class=\"rules\" style=\"margin-top:20px\">\n    <li>Siempre presentes: logo, nombre de línea en Clash Display, VLT, tecnología, años de garantía, código de rollo y QR.</li>\n    <li>Fondo blanco, texto negro, tira de bandera al pie. Sin fotos en la etiqueta.</li>\n    <li>El código de rollo se imprime completo y en tipografía monoespaciada o DM Sans, para que se pueda leer y tipear sin errores.</li>\n    <li>Muestrarios: cada muestra lleva línea y VLT. El orden va de más clara a más oscura.</li>\n    <li>Cajas y bolsas: logo y tira de bandera. Ningún dato técnico que pueda quedar desactualizado.</li>\n  </ul>\n</section>\n\n</main>\n</div>\n<div class=\"flag\" aria-hidden=\"true\" style=\"margin-top:64px\"><i></i><i></i><i></i></div>\n<footer class=\"site\"><div class=\"in\">\n  <div><img src=\"/cat/logob.svg\" alt=\"Kristall\"><p>Kristall Film · Guía de marca v1.3 · Noviembre 2026. Las especificaciones de componentes web (espaciados, radios, sombras) están en <code>kristall-web/docs/design.md</code>. Lo marcado como <span class=\"pending\">a definir</span> todavía no está decidido.</p></div>\n  <p class=\"tl\">Performance aplicada al confort.</p>\n</div></footer>\n\n</body></html>\n"
